<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='save'){$title=trim((string)($_POST['title']??''));$details=trim((string)($_POST['details']??''));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['active'])?1:0;if($id){$st=$pdo->prepare('UPDATE services SET title=?,details=?,sort_order=?,active=? WHERE id=?');$st->execute([$title,$details,$sort,$active,$id]);}else{$st=$pdo->prepare('INSERT INTO services(title,details,sort_order,active) VALUES(?,?,?,?)');$st->execute([$title,$details,$sort,$active]);}flash('success','Service saved.');}
 if($action==='delete'&&$id){$pdo->prepare('DELETE FROM services WHERE id=?')->execute([$id]);flash('success','Service deleted.');}header('Location: services.php');exit;}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM services WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$rows=$pdo->query('SELECT * FROM services ORDER BY sort_order,id')->fetchAll();$pageTitle='Services';$active='services';require __DIR__.'/_header.php';?>
<p class="eyebrow">SERVICES</p><h1>Manage services</h1><section class="panel"><h2><?=$edit?'Edit service':'Add service'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h((string)($edit['id']??''))?>"><div class="two-col"><label>Title<input name="title" required value="<?=h($edit['title']??'')?>"></label><label>Order<input type="number" name="sort_order" value="<?=h((string)($edit['sort_order']??0))?>"></label></div><label>Subservices / details<textarea name="details" required><?=h($edit['details']??'')?></textarea></label><label class="check-row"><input type="checkbox" name="active" <?=!$edit||!empty($edit['active'])?'checked':''?>> Active</label><button>Save service</button></form></section><div class="table-wrap"><table class="admin-table"><thead><tr><th>Order</th><th>Service</th><th>Details</th><th>Active</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['sort_order']?></td><td><strong><?=h($r['title'])?></strong></td><td><?=h($r['details'])?></td><td><?=$r['active']?'Yes':'No'?></td><td><div class="row-actions"><a class="button secondary" href="?edit=<?=$r['id']?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Delete this service?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_footer.php';
